    public string? RecipientEmail { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string? Notes { get; set; }
}

using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<ShipmentDto>> GetShipmentsAsync(string? statusFilter = null);
    Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<ShipmentDto?> GetShipmentByIdAsync(int id);
    Task<ShipmentDto> CreateShipmentAsync(ShipmentDto shipment);
    Task UpdateShipmentAsync(ShipmentDto shipment);
    Task<List<ShipmentDto>> GetMyShipmentsAsync();
}

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ClientShipmentService(HttpClient http) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetShipmentsAsync(string? statusFilter = null)
    {
        var url = "/api/shipments";
        if (!string.IsNullOrEmpty(statusFilter))
            url += $"?status={Uri.EscapeDataString(statusFilter)}";
        return await http.GetFromJsonAsync<List<ShipmentDto>>(url) ?? [];
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        try
        {
            return await http.GetFromJsonAsync<ShipmentDto>($"/api/shipments/track/{Uri.EscapeDataString(trackingNumber)}");
        }
        catch (HttpRequestException)
        {
            return null;
        }
    }

    public async Task<ShipmentDto?> GetShipmentByIdAsync(int id)
    {
        try
        {
            return await http.GetFromJsonAsync<ShipmentDto>($"/api/shipments/{id}");
        }
        catch (HttpRequestException)
        {
            return null;
        }
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto shipment)
    {
        var response = await http.PostAsJsonAsync("/api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<ShipmentDto>() ?? shipment;
    }

    public async Task UpdateShipmentAsync(ShipmentDto shipment)
    {
        var response = await http.PutAsJsonAsync($"/api/shipments/{shipment.Id}", shipment);
        response.EnsureSuccessStatusCode();
    }

    public async Task<List<ShipmentDto>> GetMyShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments/mine") ?? [];
    }
}

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public string Status { get; set; } = "Pending";
    public string? RecipientEmail { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string? Notes { get; set; }
}

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetShipmentsAsync(string? statusFilter = null)
    {
        var query = db.Shipments.AsQueryable();
        if (!string.IsNullOrEmpty(statusFilter))
            query = query.Where(s => s.Status == statusFilter);
        return await query.Select(s => MapToDto(s)).ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return shipment is null ? null : MapToDto(shipment);
    }

    public async Task<ShipmentDto?> GetShipmentByIdAsync(int id)
    {
        var shipment = await db.Shipments.FindAsync(id);
        return shipment is null ? null : MapToDto(shipment);
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto dto)
    {
        var shipment = new Shipment
        {
            TrackingNumber = dto.TrackingNumber,
            Origin = dto.Origin,
            Destination = dto.Destination,
            Status = dto.Status,
            RecipientEmail = dto.RecipientEmail,
            ShippedDate = dto.ShippedDate,
            EstimatedDelivery = dto.EstimatedDelivery,
            ActualDelivery = dto.ActualDelivery,
            Notes = dto.Notes
        };
        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();
        return MapToDto(shipment);
    }

    public async Task UpdateShipmentAsync(ShipmentDto dto)
    {
        var shipment = await db.Shipments.FindAsync(dto.Id)
            ?? throw new InvalidOperationException("Shipment not found");
        shipment.Origin = dto.Origin;
        shipment.Destination = dto.Destination;
        shipment.Status = dto.Status;
        shipment.RecipientEmail = dto.RecipientEmail;
        shipment.EstimatedDelivery = dto.EstimatedDelivery;
        shipment.ActualDelivery = dto.ActualDelivery;
        shipment.Notes = dto.Notes;
        await db.SaveChangesAsync();
    }

    public async Task<List<ShipmentDto>> GetMyShipmentsAsync()
    {
        // This is called via API with email filter applied at the endpoint level
        return await GetShipmentsAsync();
    }

    public async Task<List<ShipmentDto>> GetShipmentsByEmailAsync(string email)
    {
        return await db.Shipments
            .Where(s => s.RecipientEmail == email)
            .Select(s => MapToDto(s))
            .ToListAsync();
    }

    private static ShipmentDto MapToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status,
        RecipientEmail = s.RecipientEmail,
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        ActualDelivery = s.ActualDelivery,
        Notes = s.Notes
    };
}

