// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

// Seed roles and demo data
using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
    db.Database.Migrate();

    var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();
    foreach (var role in new[] { "Dispatcher", "Customer" })
    {
        if (!await roleManager.RoleExistsAsync(role))
            await roleManager.CreateAsync(new IdentityRole(role));
    }

    var userManager = scope.ServiceProvider.GetRequiredService<UserManager<ApplicationUser>>();

    if (await userManager.FindByEmailAsync("dispatcher@example.com") is null)
    {
        var dispatcher = new ApplicationUser { UserName = "dispatcher@example.com", Email = "dispatcher@example.com", EmailConfirmed = true };
        await userManager.CreateAsync(dispatcher, "Pass123!");
        await userManager.AddToRoleAsync(dispatcher, "Dispatcher");
    }

    if (await userManager.FindByEmailAsync("customer@example.com") is null)
    {
        var customer = new ApplicationUser { UserName = "customer@example.com", Email = "customer@example.com", EmailConfirmed = true };
        await userManager.CreateAsync(customer, "Pass123!");
        await userManager.AddToRoleAsync(customer, "Customer");
    }

    if (!db.Shipments.Any())
    {
        db.Shipments.AddRange(
            new Shipment { TrackingNumber = "SHP-AB12CD34", Origin = "New York", Destination = "Los Angeles", Status = "In Transit", RecipientEmail = "customer@example.com", ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(2), Notes = "Fragile items" },
            new Shipment { TrackingNumber = "SHP-EF56GH78", Origin = "Chicago", Destination = "Miami", Status = "Pending", RecipientEmail = "customer@example.com", ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(5) },
            new Shipment { TrackingNumber = "SHP-IJ90KL12", Origin = "Seattle", Destination = "Denver", Status = "Delivered", RecipientEmail = "someone@example.com", ShippedDate = DateTime.UtcNow.AddDays(-7), EstimatedDelivery = DateTime.UtcNow.AddDays(-2), ActualDelivery = DateTime.UtcNow.AddDays(-2) },
            new Shipment { TrackingNumber = "SHP-MN34OP56", Origin = "Boston", Destination = "Houston", Status = "Delayed", RecipientEmail = "customer@example.com", ShippedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow.AddDays(-1), Notes = "Weather delay" }
        );
        await db.SaveChangesAsync();
    }
}

// Minimal API endpoints
var api = app.MapGroup("/api/shipments");

api.MapGet("/", async (string? status, ServerShipmentService svc) =>
    Results.Ok(await svc.GetShipmentsAsync(status)));

api.MapGet("/track/{trackingNumber}", async (string trackingNumber, ServerShipmentService svc) =>
{
    var shipment = await svc.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
});

api.MapGet("/mine", async (HttpContext ctx, ServerShipmentService svc) =>
{
    var email = ctx.User.Identity?.Name;
    if (string.IsNullOrEmpty(email)) return Results.Unauthorized();
    return Results.Ok(await svc.GetShipmentsByEmailAsync(email));
}).RequireAuthorization();

api.MapGet("/{id:int}", async (int id, ServerShipmentService svc) =>
{
    var shipment = await svc.GetShipmentByIdAsync(id);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
}).RequireAuthorization();

api.MapPost("/", async (ShipmentTracker.Client.Models.ShipmentDto dto, ServerShipmentService svc) =>
{
    var created = await svc.CreateShipmentAsync(dto);
    return Results.Created($"/api/shipments/{created.Id}", created);
}).RequireAuthorization(p => p.RequireRole("Dispatcher"));

api.MapPut("/{id:int}", async (int id, ShipmentTracker.Client.Models.ShipmentDto dto, ServerShipmentService svc) =>
{
    dto.Id = id;
    await svc.UpdateShipmentAsync(dto);
    return Results.NoContent();
}).RequireAuthorization(p => p.RequireRole("Dispatcher"));

app.Run();

