@code {
    private ShipmentDto shipment = new();
    private DateTime estimatedDelivery = DateTime.Today.AddDays(7);
    private bool isSaving;
    private string? errorMessage;

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(shipment.Origin) || string.IsNullOrWhiteSpace(shipment.Destination))
        {
            errorMessage = "Origin and Destination are required.";
            return;
        }

        isSaving = true;
        errorMessage = null;

        shipment.TrackingNumber = "SHP-" + Guid.NewGuid().ToString("N")[..8].ToUpperInvariant();
        shipment.Status = "Pending";
        shipment.ShippedDate = DateTime.UtcNow;
        shipment.EstimatedDelivery = estimatedDelivery;

        var created = await ShipmentService.CreateShipmentAsync(shipment);
        Nav.NavigateTo($"/shipments/{created.Id}");
    }
}

