@page "/"
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="mb-3" style="max-width: 500px;">
    <label class="form-label">Enter Tracking Number</label>
    <div class="input-group">
        <input type="text" class="form-control" @bind="trackingNumber" @bind:event="oninput"
               placeholder="e.g. SHP-AB12CD34" />
        <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
            @if (isLoading) { <span class="spinner-border spinner-border-sm me-1"></span> }
            Track
        </button>
    </div>
</div>

@if (errorMessage is not null)
{
    <div class="alert alert-warning">@errorMessage</div>
}

@if (shipment is not null)
{
    <div class="card" style="max-width: 500px;">
        <div class="card-header">
            <strong>@shipment.TrackingNumber</strong>
        </div>
        <div class="card-body">
            <p><strong>Status:</strong> <span class="badge bg-@GetStatusColor(shipment.Status)">@shipment.Status</span></p>
            <p><strong>Origin:</strong> @shipment.Origin</p>
            <p><strong>Destination:</strong> @shipment.Destination</p>
            <p><strong>Shipped:</strong> @shipment.ShippedDate.ToString("MMM dd, yyyy")</p>
            <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
            @if (shipment.ActualDelivery.HasValue)
            {
                <p><strong>Delivered:</strong> @shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</p>
            }
            @if (!string.IsNullOrEmpty(shipment.Notes))
            {
                <p><strong>Notes:</strong> @shipment.Notes</p>
            }
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private ShipmentDto? shipment;
    private string? errorMessage;
    private bool isLoading;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isLoading = true;
        errorMessage = null;
        shipment = null;

        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
        if (shipment is null)
            errorMessage = "No shipment found with that tracking number.";

        isLoading = false;
    }

    private static string GetStatusColor(string status) => status switch
    {
        "Pending" => "secondary",
        "In Transit" => "primary",
        "Delivered" => "success",
        "Delayed" => "danger",
        _ => "info"
    };
}

