1. @page "/"
2. @inject IShipmentService ShipmentService
3. 
4. <PageTitle>Track Shipment</PageTitle>
5. 
6. <h1>Track Your Shipment</h1>
7. 
8. <div class="mb-3" style="max-width: 500px;">
9.     <label class="form-label">Enter Tracking Number</label>
10.     <div class="input-group">
11.         <input type="text" class="form-control" @bind="trackingNumber" @bind:event="oninput"
12.                placeholder="e.g. SHP-AB12CD34" />
13.         <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
14.             @if (isLoading) { <span class="spinner-border spinner-border-sm me-1"></span> }
15.             Track
16.         </button>
17.     </div>
18. </div>
19. 
20. @if (errorMessage is not null)
21. {
22.     <div class="alert alert-warning">@errorMessage</div>
23. }
24. 
25. @if (shipment is not null)
26. {
27.     <div class="card" style="max-width: 500px;">
28.         <div class="card-header">
29.             <strong>@shipment.TrackingNumber</strong>
30.         </div>
31.         <div class="card-body">
32.             <p><strong>Status:</strong> <span class="badge bg-@GetStatusColor(shipment.Status)">@shipment.Status</span></p>
33.             <p><strong>Origin:</strong> @shipment.Origin</p>
34.             <p><strong>Destination:</strong> @shipment.Destination</p>
35.             <p><strong>Shipped:</strong> @shipment.ShippedDate.ToString("MMM dd, yyyy")</p>
36.             <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
37.             @if (shipment.ActualDelivery.HasValue)
38.             {
39.                 <p><strong>Delivered:</strong> @shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</p>
40.             }
41.             @if (!string.IsNullOrEmpty(shipment.Notes))
42.             {
43.                 <p><strong>Notes:</strong> @shipment.Notes</p>
44.             }
45.         </div>
46.     </div>
47. }
48. 
49. @code {
50.     private string trackingNumber = string.Empty;
51.     private ShipmentDto? shipment;
52.     private string? errorMessage;
53.     private bool isLoading;
54. 
55.     private async Task TrackShipment()
56.     {
57.         if (string.IsNullOrWhiteSpace(trackingNumber)) return;
58.         isLoading = true;
59.         errorMessage = null;
60.         shipment = null;
61. 
62.         shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
63.         if (shipment is null)
64.             errorMessage = "No shipment found with that tracking number.";
65. 
66.         isLoading = false;
67.     }
68. 
69.     private static string GetStatusColor(string status) => status switch
70.     {
71.         "Pending" => "secondary",
72.         "In Transit" => "primary",
73.         "Delivered" => "success",
74.         "Delayed" => "danger",
75.         _ => "info"
76.     };
77. }
