 @page "/shipments"
 @using Microsoft.AspNetCore.Authorization
 @attribute [Authorize(Roles = "Dispatcher")]
 @inject IShipmentService ShipmentService
 @inject NavigationManager Nav

 <PageTitle>Shipments</PageTitle>

 <h1>Shipment Dashboard</h1>

 <div class="d-flex justify-content-between align-items-center mb-3">
     <div>
         <label class="form-label me-2">Filter by Status:</label>
         <select class="form-select d-inline-block" style="width: auto;" @onchange="OnFilterChanged">
             <option value="">All</option>
             <option value="Pending">Pending</option>
             <option value="In Transit">In Transit</option>
             <option value="Delivered">Delivered</option>
             <option value="Delayed">Delayed</option>
         </select>
     </div>
     <button class="btn btn-success" @onclick="GoToNewShipment">+ New Shipment</button>
 </div>

 @if (shipments is null)
 {
     <p><em>Loading...</em></p>
 }
 else if (shipments.Count == 0)
 {
     <p>No shipments found.</p>
 }
 else
 {
     <table class="table table-striped">
         <thead>
             <tr>
                 <th>Tracking #</th>
                 <th>Origin</th>
                 <th>Destination</th>
                 <th>Status</th>
                 <th>Shipped</th>
                 <th>Est. Delivery</th>
                 <th></th>
             </tr>
         </thead>
         <tbody>
             @foreach (var s in shipments)
             {
                 <tr>
                     <td>@s.TrackingNumber</td>
                     <td>@s.Origin</td>
                     <td>@s.Destination</td>
                     <td><span class="badge bg-@GetStatusColor(s.Status)">@s.Status</span></td>
                     <td>@s.ShippedDate.ToString("MMM dd, yyyy")</td>
                     <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                     <td><a href="/shipments/@s.Id" class="btn btn-sm btn-outline-primary">View</a></td>
                 </tr>
             }
         </tbody>
     </table>
 }

 @code {
     private List<ShipmentDto>? shipments;
     private string? currentFilter;

