 @page "/shipments/{Id:int}"
 @using Microsoft.AspNetCore.Authorization
 @attribute [Authorize]
 @inject IShipmentService ShipmentService
 @inject NavigationManager Nav

 <PageTitle>Shipment Detail</PageTitle>

 @if (shipment is null)
 {
     <p><em>Loading...</em></p>
 }
 else
 {
     <h1>Shipment @shipment.TrackingNumber</h1>

     <div class="row" style="max-width: 600px;">
         <div class="mb-3">
             <label class="form-label">Origin</label>
             <input class="form-control" value="@shipment.Origin" disabled />
         </div>
         <div class="mb-3">
             <label class="form-label">Destination</label>
             <input class="form-control" value="@shipment.Destination" disabled />
         </div>
         <div class="mb-3">
             <label class="form-label">Recipient Email</label>
             <input class="form-control" value="@shipment.RecipientEmail" disabled />
         </div>
         <div class="mb-3">
             <label class="form-label">Shipped Date</label>
             <input class="form-control" value="@shipment.ShippedDate.ToString("yyyy-MM-dd")" disabled />
         </div>
         <div class="mb-3">
             <label class="form-label">Estimated Delivery</label>
             <input class="form-control" value="@shipment.EstimatedDelivery.ToString("yyyy-MM-dd")" disabled />
         </div>

         <AuthorizeView Roles="Dispatcher">
             <Authorized>
                 <div class="mb-3">
                     <label class="form-label">Status</label>
                     <select class="form-select" @bind="shipment.Status">
                         <option value="Pending">Pending</option>
                         <option value="In Transit">In Transit</option>
                         <option value="Delivered">Delivered</option>
                         <option value="Delayed">Delayed</option>
                     </select>
                 </div>
                 <div class="mb-3">
                     <label class="form-label">Actual Delivery</label>
                     <input type="date" class="form-control" @bind="actualDeliveryDate" />
                 </div>
                 <div class="mb-3">
                     <label class="form-label">Notes</label>
                     <textarea class="form-control" @bind="shipment.Notes" rows="3"></textarea>
                 </div>
                 @if (saveMessage is not null)
                 {
                     <div class="alert alert-success">@saveMessage</div>
                 }
                 <button class="btn btn-primary" @onclick="SaveChanges" disabled="@isSaving">
                     @if (isSaving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                     Save Changes
                 </button>
             </Authorized>
             <NotAuthorized>
                 <div class="mb-3">
                     <label class="form-label">Status</label>
                     <input class="form-control" value="@shipment.Status" disabled />
                 </div>
                 @if (shipment.ActualDelivery.HasValue)
                 {
                     <div class="mb-3">
                         <label class="form-label">Actual Delivery</label>
                         <input class="form-control" value="@shipment.ActualDelivery.Value.ToString("yyyy-MM-dd")" disabled />
                     </div>
                 }
                 @if (!string.IsNullOrEmpty(shipment.Notes))
                 {
                     <div class="mb-3">
                         <label class="form-label">Notes</label>
                         <textarea class="form-control" disabled rows="3">@shipment.Notes</textarea>
                     </div>
                 }
             </NotAuthorized>
         </AuthorizeView>
     </div>
 }

 @code {
     [Parameter] public int Id { get; set; }

     private ShipmentDto? shipment;
     private DateTime? actualDeliveryDate;
     private bool isSaving;
     private string? saveMessage;

     protected override async Task OnInitializedAsync()
     {
         shipment = await ShipmentService.GetShipmentByIdAsync(Id);
         if (shipment?.ActualDelivery.HasValue == true)
             actualDeliveryDate = shipment.ActualDelivery.Value;
     }

     private async Task SaveChanges()
     {
         if (shipment is null) return;
         isSaving = true;
         saveMessage = null;
         shipment.ActualDelivery = actualDeliveryDate;
         await ShipmentService.UpdateShipmentAsync(shipment);
         saveMessage = "Shipment updated successfully.";
         isSaving = false;
     }
 }

